style.css:
/* Discord background theme */

/* Apply background image */
html, body {
    background-image: url('https://img.sanctuary.fr/fiche/origin/61749.jpg');
    background-size: cover; /* Ensure the background image covers the entire window */
    background-position: center; /* Center the background */
    background-repeat: no-repeat; /* Prevent background from repeating */
    height: 100% !important; /* Full screen height */
    margin: 0 !important; /* Remove default margin */
    padding: 0 !important; /* Remove default padding */
}

/* Global text color */
* {
    color: #FFFFFF !important; /* Set all text to white */
}

/* Customize the sidebar */
div[data-list-item-id="channels"] {
    background-color: rgba(0, 0, 0, 0.5) !important; /* Slightly transparent background */
    box-shadow: 2px 0px 10px rgba(0, 0, 0, 0.8) !important; /* Sidebar shadow */
}

/* Customize server name */
h1[class*="guildName"] {
    color: #FFFFFF !important; /* White color for the server name */
}

/* Sidebar links customization */
a {
    color: #FFFFFF !important; /* White links */
    text-decoration: none;
}

/* Hover effect for links */
a:hover {
    background-color: rgba(255, 255, 255, 0.2) !important; /* Light hover effect */
    border-radius: 5px !important;
}

/* Customizing the chat area */
div[class*="messagesWrapper"] {
    background-color: rgba(0, 0, 0, 0.7) !important; /* Transparent dark background */
    padding: 10px !important;
    border-radius: 10px !important;
}

/* Input fields (chat input box) */
div[class*="chat-input"] {
    background-color: rgba(255, 255, 255, 0.1) !important;
    border: 1px solid rgba(255, 255, 255, 0.5) !important;
    color: #FFFFFF !important;
}

/* Buttons */
button {
    background-color: rgba(255, 255, 255, 0.1) !important;
    color: #FFFFFF !important;
    padding: 10px 20px !important;
    border: 1px solid rgba(255, 255, 255, 0.5) !important;
    border-radius: 5px !important;
    cursor: pointer !important;
}

/* Hover effect on buttons */
button:hover {
    background-color: rgba(255, 255, 255, 0.3) !important;
}

/* Customize messages */
div[class*="message-"] {
    background-color: rgba(0, 0, 0, 0.6) !important; /* Dark background for messages */
    color: #FFFFFF !important; /* White text for messages */
    border-radius: 10px !important;
    padding: 10px !important;
}

/* Scrollbar customization */
::-webkit-scrollbar {
    width: 10px !important;
}

::-webkit-scrollbar-thumb {
    background-color: rgba(255, 255, 255, 0.5) !important;
    border-radius: 10px !important;
}

::-webkit-scrollbar-track {
    background-color: rgba(0, 0, 0, 0.5) !important;
}
